var doc=new BehaviorDocument(source,adapter,sourceFile:file);var list=doc.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&doc.Expression(n).StartsWith("new StudioExtensionChildren"));var first=list.Children.Single();
Check(first.Kind=="InitializerEntry"&&first.Parameters.Single().Name=="key"&&first.Children.Single().Kind=="Shoot","Imported native extension Add entries exclude their receiver from authored inputs");
var contracts=doc.EntryOverloads(list.Id);Check(contracts.Count==2&&contracts.All(c=>c.Metadata.Parameters.Count==2),"Collection creation discovers in-scope reduced extension Add overloads");
var contract=contracts.Single(c=>c.Metadata.Parameters[0].Type=="Int32");var ids=doc.Identities;var revision=doc.Revision;var created=doc.CreateCollectionEntry(list.Id,contract.Signature,new Dictionary<string,string>{{"key","2"}},new Dictionary<string,string>{{"child","new Shoot(20,count:6,fixedAngle:0,coolDown:100)"}},d=>adapter.Validate(d,entity));Check(doc.Revision==revision+1&&doc.Find(created).Children.Single().Kind=="Shoot"&&doc.Source.Contains("/* extension entry */"),"Actual extension contract creates a complete entry in one revision with original comments");
Check(doc.Undo()&&doc.Source==source&&doc.Identities.SequenceEqual(ids)&&doc.Redo()&&doc.Find(created).Kind=="InitializerEntry","Extension entry creation retains fresh identities through one Undo/Redo");
Reject(()=>doc.CreateCollectionEntry(list.Id,contract.Signature,new Dictionary<string,string>{{"key","\"wrong\""}},new Dictionary<string,string>{{"child","new Shoot(20)"}}),"Changed extension overload binding rejects instead of silently selecting another contract");
var project=new StudioProject{SourceFile=file,Source=doc.Source,EntityId=entity,Identities=doc.Identities,Player=new(Invulnerable:true)};await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project)){await native.AdvanceAsync(new(),100);Check(native.Shots.Select(s=>s.Count).SequenceEqual(new[]{6,4}),"Original extension Add insertion executes in its actual native enumeration order");}
var paramSource=source.Replace("public static void Add(this StudioExtensionChildren target,int key,CycleBehavior child)=>target.Values.Insert(0,child);","public static void Add(this StudioExtensionChildren target,int key,params CycleBehavior[] children)=>target.Values.InsertRange(0,System.Linq.Enumerable.Reverse(children));").Replace("{7,new Shoot(20,count:4,fixedAngle:0,coolDown:100)}","{7,new Shoot(20,count:4,fixedAngle:0,coolDown:100),new Shoot(20,count:2,fixedAngle:0,coolDown:100)}");var paramDoc=new BehaviorDocument(paramSource,adapter,sourceFile:file);var paramList=paramDoc.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&paramDoc.Expression(n).StartsWith("new StudioExtensionChildren"));var paramEntry=paramList.Children.Single();Check(paramEntry.Children.Single().Argument is{IsParams:true}&&paramEntry.Children.Single().Children.Count==2,"Expanded extension params inputs retain one actual native child-list contract");var paramsContract=paramDoc.EntryOverloads(paramList.Id).Single(c=>c.Metadata.Children.Single().IsParams);paramDoc.CreateCollectionEntry(paramList.Id,paramsContract.Signature,new Dictionary<string,string>{{"key","8"}},new Dictionary<string,string>{{"children","new CycleBehavior[]{new Shoot(20,count:8,fixedAngle:0,coolDown:100),new Shoot(20,count:6,fixedAngle:0,coolDown:100)}"}},d=>adapter.Validate(d,entity));Check(paramDoc.Find(paramList.Id).Children.Count==2,"Extension params creation commits a complete explicitly typed array");
var copied=paramDoc.CopyNodes([paramEntry.Id]);var pasted=paramDoc.PasteNodes(paramList.Id,2,copied,d=>adapter.Validate(d,entity)).Single();Check(pasted!=paramEntry.Id&&paramDoc.Find(pasted).Children.Single().Children.Count==2,"Extension entry clipboard retains exact reduced Add binding with independent descendants");paramDoc.Undo();paramDoc.LockedNodes.Add(paramList.Id);Reject(()=>paramDoc.CreateCollectionEntry(paramList.Id,paramsContract.Signature,new Dictionary<string,string>{{"key","9"}},new Dictionary<string,string>()),"Extension collection locks protect overload-based insertion");paramDoc.LockedNodes.Clear();
await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=paramDoc.Source,Identities=paramDoc.Identities})){await native.AdvanceAsync(new(),100);Check(native.Shots.Select(s=>s.Count).SequenceEqual(new[]{6,8,2,4}),"Original extension params reversal and authored entry order determine native attacks");}
var emptySource=source.Replace("new StudioExtensionChildren(){ /* extension entry */ {7,new Shoot(20,count:4,fixedAngle:0,coolDown:100)} }","new StudioExtensionChildren()");var emptyDoc=new BehaviorDocument(emptySource,adapter,sourceFile:file);var emptyList=emptyDoc.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&emptyDoc.Expression(n)=="new StudioExtensionChildren()");Check(emptyDoc.EntryOverloads(emptyList.Id).Count==2,"A constructor without initializer braces discovers in-scope extension contracts");emptyDoc.CreateCollectionEntry(emptyList.Id,emptyDoc.EntryOverloads(emptyList.Id).Single(c=>c.Metadata.Parameters[0].Type=="String").Signature,new Dictionary<string,string>{{"key","\"first\""}},new Dictionary<string,string>{{"child","new Shoot(20)"}},d=>adapter.Validate(d,entity));Check(emptyDoc.Find(emptyList.Id).Children.Single().Kind=="InitializerEntry","First extension Add entry materializes a preserved collection constructor");
